def unique_allocation():
    seen=set();allocated=0
    for folder in (RUN20,REPORT20):
        for p in [folder,*folder.rglob('*')]:
            if p.exists():
                s=p.stat();key=(s.st_dev,s.st_ino)
                if key not in seen:allocated+=s.st_blocks*512;seen.add(key)
    return allocated


